def transform(grid):
 h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]; cols=[]
 for r in grid:
  for j,v in enumerate(r):
   if v==2: cols.append(j)
 for j in cols:
  for i in range(h):
   if out[i][j]==0: out[i][j]=2
 for i,r in enumerate(grid):
  if 1 in r or 3 in r:
   c=next(v for v in r if v in (1,3)); out[i]=[c]*w
 return out
